import fs from 'fs';import path from 'path';const ROOT='sep18-final-load-combined',rows=[];function walk(d){if(!fs.existsSync(d))return;for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.name==='result.json'){try{rows.push(JSON.parse(fs.readFileSync(p,'utf8')))}catch{}}}}walk(ROOT);const valid=rows.filter(r=>r.httpStatus===200&&r.previewOk&&!r.error&&!r.brokenImages),invalid=rows.filter(r=>!valid.includes(r));const avg=(g,k)=>{const a=valid.filter(x=>x.group===g);return a.length?Math.round(a.reduce((s,x)=>s+(x[k]||0),0)/a.length):0};const percentile=(a,k,p)=>{const v=a.map(x=>x[k]||0).sort((x,y)=>x-y);return v.length?v[Math.min(v.length-1,Math.floor((v.length-1)*p))]:0};const ranked=[...valid].sort((a,b)=>(b.loadMs||0)-(a.loadMs||0));const summary={generatedAt:new Date().toISOString(),total:rows.length,valid:valid.length,invalid:invalid.length,counts:{homepage:rows.filter(x=>x.group==='homepage').length,stateGuardRoot:rows.filter(x=>x.group==='state-guard-root').length},averages:{homepage:{loadMs:avg('homepage','loadMs'),fcpMs:avg('homepage','fcpMs'),lcpMs:avg('homepage','lcpMs')},stateGuardRoot:{loadMs:avg('state-guard-root','loadMs'),fcpMs:avg('state-guard-root','fcpMs'),lcpMs:avg('state-guard-root','lcpMs')}},p95:{homepageLoadMs:percentile(valid.filter(x=>x.group==='homepage'),'loadMs',.95),stateGuardLoadMs:percentile(valid.filter(x=>x.group==='state-guard-root'),'loadMs',.95)},slowest:ranked.slice(0,20),invalidRows:invalid,rows};fs.mkdirSync('sep18-final-load-final',{recursive:true});fs.writeFileSync('sep18-final-load-final/summary.json',JSON.stringify(summary,null,2));fs.writeFileSync('sep18-final-load-final/AUDIT.md',['# Final Current Draft Load Certification','',`Total ${summary.total}; valid ${summary.valid}; invalid ${summary.invalid}`,`Homepage ${summary.counts.homepage}; State Guard root ${summary.counts.stateGuardRoot}`,'',`Homepage avg load: ${summary.averages.homepage.loadMs} ms; p95: ${summary.p95.homepageLoadMs} ms`,`State Guard avg load: ${summary.averages.stateGuardRoot.loadMs} ms; p95: ${summary.p95.stateGuardLoadMs} ms`,'','## Slowest',...summary.slowest.map((r,i)=>`${i+1}. ${r.group} — ${r.label} — ${r.loadMs} ms load, ${r.lcpMs} ms LCP, ${Math.round((r.transferBytes||0)/1024)} KB, attempt ${r.attempt}`),'','## Invalid',...invalid.map(r=>`- ${r.group} — ${r.label} — HTTP ${r.httpStatus}; preview=${r.previewOk}; error=${r.error||''}`)].join('\n'));console.log('FINALLOADSUMMARY',JSON.stringify({total:summary.total,valid:summary.valid,invalid:summary.invalid,counts:summary.counts,averages:summary.averages,p95:summary.p95,slowest:summary.slowest.slice(0,12).map(r=>({group:r.group,label:r.label,route:r.route,loadMs:r.loadMs,lcpMs:r.lcpMs,ttfbMs:r.ttfbMs,kb:Math.round((r.transferBytes||0)/1024),attempt:r.attempt})),invalidRows:invalid.map(r=>({group:r.group,label:r.label,route:r.route,http:r.httpStatus,attempts:r.attemptHistory}))}));if(invalid.length)process.exitCode=2;